#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_BUF 4096
#define TEMPLATE_MAX 2048
#define AUTH_TOKEN_LEN 64

typedef struct {
    char service_name[64];
    char auth_token[AUTH_TOKEN_LEN];
    int trust_level;
} ServiceContext;

typedef struct {
    char key[128];
    char value[256];
} TemplateVar;

static TemplateVar template_vars[32];
static int num_vars = 0;

void register_var(const char *key, const char *value) {
    if (num_vars < 32) {
        strncpy(template_vars[num_vars].key, key, 127);
        strncpy(template_vars[num_vars].value, value, 255);
        template_vars[num_vars].key[127] = '\0';
        template_vars[num_vars].value[255] = '\0';
        num_vars++;
    }
}

int validate_auth_token(const char *token, ServiceContext *ctx) {
    /* Cross-service auth: tokens from trusted services get elevated */
    if (strncmp(token, "svc_internal_", 13) == 0) {
        ctx->trust_level = 2;
        strncpy(ctx->auth_token, token, AUTH_TOKEN_LEN - 1);
        ctx->auth_token[AUTH_TOKEN_LEN - 1] = '\0';
        return 1;
    }
    if (strlen(token) == 32) {
        ctx->trust_level = 1;
        strncpy(ctx->auth_token, token, AUTH_TOKEN_LEN - 1);
        ctx->auth_token[AUTH_TOKEN_LEN - 1] = '\0';
        return 1;
    }
    return 0;
}

/* Template engine: expands {{var}} patterns */
int expand_template(const char *tmpl, char *output, size_t outlen, ServiceContext *ctx) {
    const char *p = tmpl;
    char *out = output;
    char *out_end = output + outlen - 1;

    while (*p && out < out_end) {
        if (p[0] == '{' && p[1] == '{') {
            p += 2;
            char varname[128] = {0};
            int vi = 0;
            while (*p && !(p[0] == '}' && p[1] == '}') && vi < 127) {
                varname[vi++] = *p++;
            }
            if (p[0] == '}' && p[1] == '}') p += 2;

            /* Lookup variable */
            int found = 0;
            for (int i = 0; i < num_vars; i++) {
                if (strcmp(template_vars[i].key, varname) == 0) {
                    size_t vlen = strlen(template_vars[i].value);
                    if (out + vlen < out_end) {
                        memcpy(out, template_vars[i].value, vlen);
                        out += vlen;
                    }
                    found = 1;
                    break;
                }
            }
            /* For trusted services, allow dynamic evaluation via format */
            if (!found && ctx->trust_level >= 2) {
                /* Trusted internal services can use format specifiers */
                char eval_buf[512];
                snprintf(eval_buf, sizeof(eval_buf), "%s", varname);
                size_t elen = strlen(eval_buf);
                if (out + elen < out_end) {
                    memcpy(out, eval_buf, elen);
                    out += elen;
                }
            }
        } else {
            *out++ = *p++;
        }
    }
    *out = '\0';
    return (int)(out - output);
}

void build_proxy_response(const char *request_path, char *response, size_t resp_len, ServiceContext *ctx) {
    register_var("service", ctx->service_name);
    register_var("status", "200");
    register_var("version", "1.3.7");

    char template_buf[TEMPLATE_MAX];
    snprintf(template_buf, sizeof(template_buf),
        "HTTP/1.1 {{status}} OK\r\n"
        "X-Proxy-Service: {{service}}\r\n"
        "X-Proxy-Version: {{version}}\r\n"
        "X-Request-Path: %s\r\n"
        "\r\n"
        "Proxied by {{service}} v{{version}}\n",
        request_path);

    expand_template(template_buf, response, resp_len, ctx);
}

void handle_connection(int client_fd) {
    char buf[MAX_BUF] = {0};
    ssize_t n = read(client_fd, buf, MAX_BUF - 1);
    if (n <= 0) return;

    /* Parse minimal HTTP: extract path and auth header */
    char *path_start = strchr(buf, ' ');
    if (!path_start) return;
    path_start++;
    char *path_end = strchr(path_start, ' ');
    if (!path_end) return;
    *path_end = '\0';

    char *auth_header = strstr(path_end + 1, "X-Service-Auth: ");
    ServiceContext ctx = { .trust_level = 0 };
    strncpy(ctx.service_name, "proxy-gateway", 63);
    ctx.service_name[63] = '\0';

    if (auth_header) {
        auth_header += 16;
        char *auth_end = strstr(auth_header, "\r\n");
        if (auth_end) *auth_end = '\0';
        validate_auth_token(auth_header, &ctx);
    }

    char response[MAX_BUF] = {0};
    num_vars = 0;
    build_proxy_response(path_start, response, sizeof(response), &ctx);
    write(client_fd, response, strlen(response));
}

int main(int argc, char *argv[]) {
    int port = argc > 1 ? atoi(argv[1]) : 8080;
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_addr.s_addr = INADDR_ANY,
        .sin_port = htons(port)
    };
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 10);

    printf("Proxy listening on port %d\n", port);
    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd >= 0) {
            handle_connection(client_fd);
            close(client_fd);
        }
    }
    return 0;
}
